import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = sc.nextInt();
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        while (q-- > 0) {
            String op = sc.next();
            if (op.equals("ADD")) {
                pq.add(sc.nextInt());
            } else if (op.equals("PEEK")) {
                if (pq.isEmpty()) System.out.println("Empty");
                else System.out.println(pq.peek());
            } else if (op.equals("POLL")) {
                if (pq.isEmpty()) System.out.println("Empty");
                else System.out.println(pq.poll());
            } else if (op.equals("SIZE")) {
                System.out.println(pq.size());
            }
        }
    }
}

import java.util.HashMap;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = sc.nextInt();
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        HashMap<Integer, String> byToken = new HashMap<>();
        while (q-- > 0) {
            String op = sc.next();
            if (op.equals("ARRIVE")) {
                String name = sc.next();
                int token = sc.nextInt();
                pq.add(token);
                byToken.put(token, name);
            } else if (op.equals("NEXT")) {
                if (pq.isEmpty()) System.out.println("No patients");
                else System.out.println(byToken.get(pq.peek()));
            } else if (op.equals("SERVE")) {
                if (pq.isEmpty()) System.out.println("No patients");
                else System.out.println(byToken.get(pq.poll()));
            } else if (op.equals("COUNT")) {
                System.out.println(pq.size());
            }
        }
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            if (pq.size() < k) {
                pq.add(x);
            } else if (x > pq.peek()) {
                pq.poll();
                pq.add(x);
            }
        }
        int[] top = new int[pq.size()];
        int idx = top.length - 1;
        while (!pq.isEmpty()) {
            top[idx--] = pq.poll();
        }
        for (int v : top) {
            System.out.println(v);
        }
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            pq.add(sc.nextLong());
        }
        long total = 0;
        while (pq.size() > 1) {
            long a = pq.poll();
            long b = pq.poll();
            long merged = a + b;
            total += merged;
            pq.add(merged);
        }
        System.out.println(total);
    }
}

import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = sc.nextInt();
        HashMap<String, String> map = new HashMap<>();
        while (q-- > 0) {
            String op = sc.next();
            if (op.equals("PUT")) {
                String key = sc.next();
                String value = sc.next();
                System.out.println(map.put(key, value));
            } else if (op.equals("GET")) {
                System.out.println(map.get(sc.next()));
            } else if (op.equals("CONTAINS")) {
                System.out.println(map.containsKey(sc.next()));
            } else if (op.equals("SIZE")) {
                System.out.println(map.size());
            }
        }
    }
}

import java.util.HashMap;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        HashMap<String, Integer> stock = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String sku = sc.next();
            int qty = sc.nextInt();
            if (stock.containsKey(sku)) {
                int old = stock.get(sku);
                stock.put(sku, qty);
                System.out.println(sku + ": " + old + " -> " + qty);
            } else {
                stock.put(sku, qty);
                System.out.println(sku + ": inserted " + qty);
            }
        }
        System.out.println("Size: " + stock.size());
    }
}
